# backend/packages/brand_icons.py
"""Embedded standalone Brand Icons for popular Windows software."""

from typing import Optional, Dict

BRAND_ICONS: Dict[str, str] = {
    'chrome': 'data:image/png;base64,',
    'vlc': 'data:image/png;base64,',
    'firefox': 'data:image/png;base64,',
    'winrar': 'data:image/png;base64,',
    'kmplayer': 'data:image/png;base64,',
    'fdm': 'data:image/png;base64,',
    'acrobat': 'data:image/png;base64,',
}

def get_embedded_brand_icon(name_or_filename: str) -> Optional[str]:
    """Resolves an embedded brand icon for well-known software by matching identity keywords."""
    if not name_or_filename:
        return None
    s = name_or_filename.lower()
    
    if "chrome" in s or "google chrome" in s:
        return BRAND_ICONS.get("chrome")
    if "vlc" in s or "videolan" in s:
        return BRAND_ICONS.get("vlc")
    if "firefox" in s or "mozilla" in s:
        return BRAND_ICONS.get("firefox")
    if "winrar" in s or "rar" in s:
        return BRAND_ICONS.get("winrar")
    if "kmplayer" in s or "kmp" in s:
        return BRAND_ICONS.get("kmplayer")
    if "fdm" in s or "download manager" in s:
        return BRAND_ICONS.get("fdm")
    if "acrobat" in s or "adobe reader" in s or "acroread" in s:
        return BRAND_ICONS.get("acrobat")
    
    return None
